package com.mendes.scheduling_platform.booking; import com.mendes.scheduling_platform.security.TenantContext; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/bookings") public class BookingController {private final BookingService service;public BookingController(BookingService s){service=s;}record StatusRequest(Booking.Status status,Booking.PaymentStatus paymentStatus){}@GetMapping List<Booking> list(){return service.list(TenantContext.getRequired());}@PatchMapping("/{id}") Booking update(@PathVariable Long id,@RequestBody StatusRequest r){return service.status(TenantContext.getRequired(),id,r.status(),r.paymentStatus());}}
